def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    day = day_context['day']
    supply = float(day_context['supply'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    for opp_id in opponents_status:
        opp = opponents_status[opp_id]
        if opp.get('alive'):
            alive_opponents.append(opp)

    if not alive_opponents:
        base = DAILY_SALARY * 0.35
        if hp <= 3 or no_water_days >= 1:
            base = DAILY_SALARY * 0.6
        return max(0.0, min(float(budget), float(base)))

    prev_bids = []
    urgent_count = 0
    rich_count = 0
    for opp in alive_opponents:
        if opp.get('budget', 0) >= DAILY_SALARY * 4:
            rich_count += 1
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
            urgent_count += 1
        prev = opp.get('previous_trace', {})
        if prev:
            bid = prev.get('bid')
            if bid is not None:
                try:
                    prev_bids.append(float(bid))
                except Exception:
                    pass

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    supply_ratio = (supply - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY)
    if supply_ratio < 0:
        supply_ratio = 0.0
    if supply_ratio > 1:
        supply_ratio = 1.0

    scarcity = 1.0 - supply_ratio

    if hp <= 2:
        bid = max(DAILY_SALARY * 0.95, highest_prev + 2.0)
    elif no_water_days >= 2:
        bid = max(DAILY_SALARY * 0.9, highest_prev + 1.5)
    elif no_water_days == 1 or hp <= 4:
        bid = max(DAILY_SALARY * (0.68 + 0.18 * scarcity), avg_prev + 1.0)
    else:
        bid = DAILY_SALARY * (0.32 + 0.28 * scarcity)
        if highest_prev > 0:
            target = avg_prev + 1.0
            cap = DAILY_SALARY * (0.62 + 0.12 * scarcity)
            if target > bid:
                bid = min(target, cap)

    if urgent_count >= 2:
        bid += 4.0 * scarcity
    elif urgent_count == 1:
        bid += 2.0 * scarcity

    if rich_count >= 2 and scarcity > 0.5:
        bid += 3.0

    if day >= 8 and hp >= 6 and no_water_days == 0:
        bid *= 0.92

    if budget < DAILY_SALARY * 2:
        bid = min(bid, budget * 0.72)
    elif budget < DAILY_SALARY * 4:
        bid = min(bid, budget * 0.55)

    min_survival_bid = 0.0
    if hp <= 3:
        min_survival_bid = DAILY_SALARY * 0.75
    elif no_water_days >= 1:
        min_survival_bid = DAILY_SALARY * 0.58

    if bid < min_survival_bid:
        bid = min_survival_bid

    if supply >= 23 and hp >= 7 and no_water_days == 0:
        bid = min(bid, DAILY_SALARY * 0.34)

    bid = max(0.0, min(float(budget), float(bid)))
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10
    MIN_BID_FRACTION = 0.4
    HIGH_BID_FRACTION = 0.95
    CRITICAL_HP = 3

    STRONG_BIDDERS_META = ["Alex", "David"]

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * MIN_BID_FRACTION * 0.5)

    yesterday_bids = []
    strong_opponent_yesterday_bids = []

    for agent_id, opp in opponents_status.items():
        if opp['alive']:
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                yesterday_bids.append(prev['bid'])
                if agent_id in STRONG_BIDDERS_META:
                    strong_opponent_yesterday_bids.append(prev['bid'])

    highest_prev_bid = 0
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

    highest_strong_bid = 0
    if strong_opponent_yesterday_bids:
        highest_strong_bid = max(strong_opponent_yesterday_bids)

    current_day = day_context['day']
    remaining_days = EPISODE_DAYS - current_day + 1

    base_bid = DAILY_SALARY * MIN_BID_FRACTION

    if my_status['hp'] <= CRITICAL_HP:
        base_bid = DAILY_SALARY * HIGH_BID_FRACTION
        if my_status['hp'] <= 1:
            base_bid = DAILY_SALARY + 10
    elif my_status['hp'] <= CRITICAL_HP + 2:
        base_bid = max(base_bid, DAILY_SALARY * 0.7)

    if remaining_days <= 3:
        base_bid = max(base_bid, DAILY_SALARY * 0.85)
        if my_status['hp'] <= CRITICAL_HP + 1:
             base_bid = max(base_bid, DAILY_SALARY * 0.95)
    elif remaining_days <= 5:
        base_bid = max(base_bid, DAILY_SALARY * 0.6)

    competitive_bid_from_opponents = highest_strong_bid if highest_strong_bid > 0 else highest_prev_bid

    if competitive_bid_from_opponents > 0:
        if competitive_bid_from_opponents >= DAILY_SALARY * 0.8:
            if my_status['hp'] > CRITICAL_HP:
                base_bid = max(base_bid, competitive_bid_from_opponents + 1)
            else:
                base_bid = max(base_bid, competitive_bid_from_opponents + 5)
        else:
            base_bid = max(base_bid, competitive_bid_from_opponents + 1)

    if day_context['supply'] < WATER_REQ * 1.5:
        if len(alive_opponents) >= 1:
            base_bid = max(base_bid, DAILY_SALARY * 0.8)
            if my_status['hp'] <= CRITICAL_HP:
                base_bid = max(base_bid, DAILY_SALARY + 15)

    bid = min(base_bid, my_status['budget'])

    if bid <= 0 and my_status['budget'] > 0:
        bid = min(my_status['budget'], 1.0)
    elif bid <= 0:
        bid = 0.0

    return bid
